export function renderMoveHighlight(board: HTMLElement, fromRank: number, fromFile: number, toRank: number, toFile: number) {
  const fromSquare = document.querySelector(`.square[data-rank="${fromRank}"][data-file="${fromFile}"]`);
  const toSquare = document.querySelector(`.square[data-rank="${toRank}"][data-file="${toFile}"]`);
  if (fromSquare) fromSquare.classList.add('selected');
  if (toSquare) toSquare.classList.add('highlight');
}

export function renderCheck(board: HTMLElement, isWhiteChecked: boolean) {
  const check = document.createElement('div');
  check.className = 'check';
  if (isWhiteChecked) {
    check.textContent = '♔';
  } else {
    check.textContent = '♚';
  }
  board.appendChild(check);
}

